Finding jvm_class_finding(const JvmClassInfo&i){Finding f;f.kind="bytecode";f.family="JVM Class";f.variant=i.java_release+(i.preview?" preview":"");if(!i.valid){f.state="FAILED";if(!i.error.empty()){std::ostringstream o;o<<i.error<<" at 0x"<<std::hex<<i.error_offset;f.negative_evidence.push_back(o.str());}return f;}f.state="CONFIRMED";f.evidence={"CAFEBABE header, version, constant-pool tags/indexes and full ClassFile geometry validated","field/method descriptors decoded and Code attribute file ranges recovered"};if(i.bootstrap_method_count)f.evidence.push_back("BootstrapMethods structure validated for dynamic call-site metadata");if(i.kotlin_metadata)f.evidence.push_back("kotlin.Metadata annotation structurally decoded");f.fields["class"]=i.class_name;f.fields["super"]=i.super_name;f.fields["major"]=std::to_string(i.major);f.fields["minor"]=std::to_string(i.minor);f.fields["constant_pool"]=std::to_string(i.constant_pool_count);f.fields["fields"]=std::to_string(i.fields.size());f.fields["methods"]=std::to_string(i.methods.size());f.fields["references"]=std::to_string(i.references.size());f.fields["strings"]=std::to_string(i.string_constants.size());f.fields["invokedynamic"]=std::to_string(i.invokedynamic_count);f.fields["bootstrap_methods"]=std::to_string(i.bootstrap_method_count);if(!i.source_file.empty())f.fields["source_file"]=i.source_file;if(!i.module_name.empty())f.fields["module"]=i.module_name;if(!i.descriptor_parse_complete)f.negative_evidence.push_back("one or more field/method descriptors were malformed");for(const auto&x:i.obfuscation_hints)f.negative_evidence.push_back("obfuscation/anomaly hint only: "+x);for(std::size_t n=0;n<std::min<std::size_t>(i.anomalies.size(),16);n++)f.negative_evidence.push_back(i.anomalies[n]);f.suggested_actions={"extract:jvm-function-map","inspect methods with Code offsets and user-package owners first","use CFR/FernFlower/JADX/Bytecode Viewer for selected classes"};return f;}
JvmExtractResult extract_jvm_maps(const JvmClassInfo&i,const std::filesystem::path&out){JvmExtractResult r;if(!i.valid){r.error="JVM class not valid";return r;}std::ofstream m(out,std::ios::binary|std::ios::trunc);if(!m){r.error="cannot create JVM method CSV";return r;}m<<"class,name,descriptor,signature,generic_signature,code_offset,code_size,max_stack,max_locals,parameter_names,exceptions,annotations,line_numbers\n";for(const auto&x:i.methods)m<<csvq(i.class_name)<<','<<csvq(x.name)<<','<<csvq(x.descriptor)<<','<<csvq(x.signature)<<','<<csvq(x.generic_signature)<<",0x"<<std::hex<<x.code_offset<<std::dec<<','<<x.code_size<<','<<x.max_stack<<','<<x.max_locals<<','<<csvq(join(x.parameter_names,"|"))<<','<<csvq(join(x.exceptions,"|"))<<','<<csvq(join(x.annotations,"|"))<<','<<x.line_number_count<<"\n";if(!m){r.error="write JVM methods CSV failed";return r;}r.methods_csv=out;r.method_count=i.methods.size();auto fp=out;fp.replace_filename(out.stem().string()+"-fields.csv");std::ofstream f(fp,std::ios::binary|std::ios::trunc);if(!f){r.error="cannot create JVM field CSV";return r;}f<<"class,name,descriptor,type,generic_signature,constant_value,annotations\n";for(const auto&x:i.fields)f<<csvq(i.class_name)<<','<<csvq(x.name)<<','<<csvq(x.descriptor)<<','<<csvq(x.type_name)<<','<<csvq(x.generic_signature)<<','<<csvq(x.constant_value)<<','<<csvq(join(x.annotations,"|"))<<"\n";r.fields_csv=fp;r.field_count=i.fields.size();auto rp=out;rp.replace_filename(out.stem().string()+"-references.csv");std::ofstream q(rp,std::ios::binary|std::ios::trunc);if(!q){r.error="cannot create JVM reference CSV";return r;}q<<"kind,owner,name,descriptor,signature\n";for(const auto&x:i.references)q<<csvq(x.kind)<<','<<csvq(x.owner)<<','<<csvq(x.name)<<','<<csvq(x.descriptor)<<','<<csvq(x.signature)<<"\n";r.references_csv=rp;r.reference_count=i.references.size();r.success=bool(f)&&bool(q);if(!r.success)r.error="write JVM CSV failed";return r;}

JarInfo detect_jar(std::span<const std::uint8_t>d,const std::filesystem::path&path){JarInfo out;bool magic=d.size()>=4&&d[0]=='P'&&d[1]=='K'&&((d[2]==3&&d[3]==4)||(d[2]==5&&d[3]==6)||(d[2]==7&&d[3]==8));auto path_text=path_utf8(path);bool ext=ends_icase(path_text,".jar")||ends_icase(path_text,".war")||ends_icase(path_text,".ear");if(!magic&&!ext)return out;out.candidate=true;if(!magic){out.error="Java archive extension present but ZIP local/end signature is missing";return out;}mz_zip_archive z{};mz_zip_zero_struct(&z);if(!mz_zip_reader_init_mem(&z,d.data(),d.size(),0)){out.error=std::string("ZIP central directory validation failed: ")+mz_zip_get_error_string(mz_zip_get_last_error(&z));mz_zip_reader_end(&z);return out;}out.zip64=mz_zip_is_zip64(&z);auto n=mz_zip_reader_get_num_files(&z);if(n>1000000){out.error="ZIP entry count unreasonable";mz_zip_reader_end(&z);return out;}out.entry_count=n;out.entries.reserve(n);int manifest_idx=-1;bool boot_classes=false,boot_lib=false;for(mz_uint k=0;k<n;k++){mz_zip_archive_file_stat st{};if(!mz_zip_reader_file_stat(&z,k,&st)){out.error="ZIP central directory entry stat failed";mz_zip_reader_end(&z);return out;}JarEntryInfo e;e.name=st.m_filename;e.compressed_size=st.m_comp_size;e.uncompressed_size=st.m_uncomp_size;e.crc32=st.m_crc32;e.method=st.m_method;e.directory=st.m_is_directory;e.encrypted=st.m_is_encrypted;e.supported=st.m_is_supported;auto safe=safe_zip_path(e.name);e.safe_path=!safe.empty();auto host=std::uint8_t(st.m_version_made_by>>8);auto mode=st.m_external_attr>>16;e.symlink=host==3&&((mode&0170000u)==0120000u);e.class_file=!e.directory&&ends_icase(e.name,".class");e.nested_archive=!e.directory&&(ends_icase(e.name,".jar")||ends_icase(e.name,".zip"));if(e.class_file)++out.class_count;if(e.nested_archive)++out.nested_archive_count;if(ends_icase(e.name,".so")||ends_icase(e.name,".dll")||ends_icase(e.name,".dylib")||ends_icase(e.name,".jnilib"))++out.native_library_count;if(e.name=="META-INF/MANIFEST.MF")manifest_idx=k;if(starts(e.name,"META-INF/versions/"))out.multi_release=true;if(starts(e.name,"BOOT-INF/classes/"))boot_classes=true;if(starts(e.name,"BOOT-INF/lib/")&&ends_icase(e.name,".jar"))boot_lib=true;if(!e.directory){if(e.uncompressed_size>std::numeric_limits<std::uint64_t>::max()-out.total_uncompressed)out.total_uncompressed=std::numeric_limits<std::uint64_t>::max();else out.total_uncompressed+=e.uncompressed_size;if(e.compressed_size>std::numeric_limits<std::uint64_t>::max()-out.total_compressed)out.total_compressed=std::numeric_limits<std::uint64_t>::max();else out.total_compressed+=e.compressed_size;}if(!e.safe_path)out.anomalies.push_back("unsafe archive path: "+e.name);if(e.symlink)out.anomalies.push_back("symlink archive entry refused: "+e.name);if(e.class_file||e.nested_archive||starts(e.name,"META-INF/services/")||starts(e.name,"BOOT-INF/")||e.name=="META-INF/MANIFEST.MF")if(out.interesting_entries.size()<256)out.interesting_entries.push_back(e.name);out.entries.push_back(std::move(e));}
    if(manifest_idx>=0){mz_zip_archive_file_stat st{};if(mz_zip_reader_file_stat(&z,manifest_idx,&st)&&st.m_uncomp_size<=1024*1024&&st.m_is_supported&&!st.m_is_encrypted){std::vector<char>b(static_cast<std::size_t>(st.m_uncomp_size));if(mz_zip_reader_extract_to_mem(&z,manifest_idx,b.data(),b.size(),0)){auto m=manifest_parse(std::string_view(b.data(),b.size()),out.manifest_lines);if(auto it=m.find("Main-Class");it!=m.end())out.main_class=it->second;if(auto it=m.find("Automatic-Module-Name");it!=m.end())out.automatic_module_name=it->second;if(auto it=m.find("Implementation-Version");it!=m.end())out.implementation_version=it->second;if(auto it=m.find("Multi-Release");it!=m.end()&&(it->second=="true"||it->second=="True"))out.multi_release=true;}}}
    out.spring_boot=boot_classes&&boot_lib;out.fat_jar=out.nested_archive_count>0;bool javaish=out.class_count>0||manifest_idx>=0||out.spring_boot;if(!javaish){out.error="valid ZIP structure but no class files or JAR manifest";mz_zip_reader_end(&z);return out;}out.variant=out.spring_boot?"Spring Boot fat JAR":out.fat_jar?"fat JAR":out.multi_release?"multi-release JAR":"JAR";out.valid=true;mz_zip_reader_end(&z);return out;}
Finding jar_finding(const JarInfo&i){Finding f;f.kind="container";f.family="Java/JVM archive";f.variant=i.variant;if(!i.valid){f.state="FAILED";if(!i.error.empty())f.negative_evidence.push_back(i.error);return f;}f.state="CONFIRMED";f.evidence={"ZIP central directory and per-entry geometry validated","archive contains JVM class files and/or META-INF/MANIFEST.MF"};if(i.spring_boot)f.evidence.push_back("BOOT-INF/classes plus BOOT-INF/lib layout validates Spring Boot executable archive structure");f.fields["entries"]=std::to_string(i.entry_count);f.fields["classes"]=std::to_string(i.class_count);f.fields["nested_archives"]=std::to_string(i.nested_archive_count);f.fields["native_libraries"]=std::to_string(i.native_library_count);f.fields["uncompressed_bytes"]=std::to_string(i.total_uncompressed);f.fields["compressed_bytes"]=std::to_string(i.total_compressed);if(!i.main_class.empty())f.fields["main_class"]=i.main_class;if(!i.automatic_module_name.empty())f.fields["automatic_module_name"]=i.automatic_module_name;if(!i.implementation_version.empty())f.fields["implementation_version"]=i.implementation_version;for(const auto&a:i.anomalies)f.negative_evidence.push_back(a);f.suggested_actions={"extract:jar","analyze application classes before bundled libraries","use CFR/FernFlower/JADX for selected JVM classes"};return f;}
JarExtractResult extract_jar(std::span<const std::uint8_t>d,const JarInfo&i,const std::filesystem::path&dir,std::uint64_t max_bytes,std::uint32_t max_files,bool analysis_only){JarExtractResult r;r.output_dir=dir;r.analysis_only=analysis_only;if(!i.valid){r.error="Java archive not validated";return r;}std::error_code ec;std::filesystem::create_directories(dir,ec);if(ec){r.error="cannot create JAR output directory: "+ec.message();return r;}mz_zip_archive z{};mz_zip_zero_struct(&z);if(!mz_zip_reader_init_mem(&z,d.data(),d.size(),0)){r.error="cannot reopen validated JAR";return r;}auto n=mz_zip_reader_get_num_files(&z);std::vector<bool>selected(n,!analysis_only);if(analysis_only){std::string main=i.main_class;std::replace(main.begin(),main.end(),'.','/');if(!main.empty())main += ".class";struct C{std::size_t idx;int score;std::uint64_t size;};std::vector<C>cs;for(std::size_t k=0;k<i.entries.size()&&k<n;++k){const auto&e=i.entries[k];if(e.directory||e.symlink||!e.safe_path||e.encrypted||!e.supported)continue;int score=0;if(e.name=="META-INF/MANIFEST.MF")score=1000;if(!main.empty()&&(e.name==main||e.name=="BOOT-INF/classes/"+main))score=980;if(e.class_file&&e.name.rfind("BOOT-INF/classes/",0)==0)score=900;else if(e.class_file&&e.name.rfind("META-INF/",0)!=0)score=800;if(e.nested_archive)score=std::max(score,600);if(e.name.rfind("META-INF/services/",0)==0)score=std::max(score,500);if(score)cs.push_back({k,score,e.uncompressed_size});}std::stable_sort(cs.begin(),cs.end(),[](const C&a,const C&b){return a.score!=b.score?a.score>b.score:a.idx<b.idx;});std::uint64_t used=0;std::uint32_t files=0;for(const auto&c:cs){if(files>=max_files||c.size>max_bytes-used){r.budget_exhausted=true;++r.omitted_count;r.omitted_bytes=c.size>std::numeric_limits<std::uint64_t>::max()-r.omitted_bytes?std::numeric_limits<std::uint64_t>::max():r.omitted_bytes+c.size;continue;}selected[c.idx]=true;used+=c.size;++files;}}
    for(mz_uint k=0;k<n;k++){if(analysis_only&&!selected[k])continue;mz_zip_archive_file_stat st{};if(!mz_zip_reader_file_stat(&z,k,&st)){r.error="JAR stat failed during extraction";break;}if(st.m_is_directory)continue;auto rel=safe_zip_path(st.m_filename);auto host=std::uint8_t(st.m_version_made_by>>8);auto mode=st.m_external_attr>>16;bool sym=host==3&&((mode&0170000u)==0120000u);if(rel.empty()||sym){r.warnings.push_back("refused unsafe/symlink JAR entry: "+std::string(st.m_filename));continue;}if(st.m_is_encrypted||!st.m_is_supported){r.warnings.push_back("unsupported/encrypted JAR entry: "+std::string(st.m_filename));continue;}if(st.m_uncomp_size>max_bytes-r.output_bytes||r.file_count>=max_files){r.budget_exhausted=true;++r.omitted_count;r.omitted_bytes=st.m_uncomp_size>std::numeric_limits<std::uint64_t>::max()-r.omitted_bytes?std::numeric_limits<std::uint64_t>::max():r.omitted_bytes+st.m_uncomp_size;if(!analysis_only)r.error="JAR extraction budget exhausted before entry: "+std::string(st.m_filename);continue;}std::vector<std::uint8_t>b(static_cast<std::size_t>(st.m_uncomp_size));if(st.m_uncomp_size&&!mz_zip_reader_extract_to_mem(&z,k,b.data(),b.size(),0)){r.error="JAR decompression/CRC validation failed: "+std::string(st.m_filename);break;}auto out=dir/rel;std::filesystem::create_directories(out.parent_path(),ec);if(ec){r.error="cannot create JAR child directory";break;}std::ofstream f(out,std::ios::binary|std::ios::trunc);if(!f){r.error="cannot create JAR output file";break;}f.write(reinterpret_cast<const char*>(b.data()),static_cast<std::streamsize>(b.size()));if(!f){r.error="write JAR output failed";break;}r.output_bytes+=b.size();++r.file_count;r.files.push_back(out);}mz_zip_reader_end(&z);r.success=analysis_only?(r.file_count>0&&r.error.empty()):(r.error.empty()&&!r.budget_exhausted);if(analysis_only&&r.file_count==0&&r.error.empty())r.error="no JAR analysis candidates materialized";return r;}
